//! One row per instruction: documentation, support policy, suspension and emission.

use crate::analyze::util::AResult;
use crate::decode::Decoded;
use crate::emit::{Emitter, RustValue};

pub type Emit = fn(&mut Emitter, &Decoded) -> AResult<Option<RustValue>>;

#[derive(Clone, Copy)]
pub struct OpRow {
    pub ir_name: &'static str,
    /// Documentation label; dispatch always uses `emit`.
    pub family: &'static str,
    pub support: &'static str,
    pub reason: &'static str,
    pub suspends: bool,
    pub emit: Emit,
}

impl OpRow {
    const fn new(ir_name: &'static str, family: &'static str, emit: Emit) -> Self {
        Self {
            ir_name,
            family,
            support: "modeled",
            reason: "",
            suspends: false,
            emit,
        }
    }

    const fn support(self, support: &'static str) -> Self {
        Self { support, ..self }
    }
    const fn reason(self, reason: &'static str) -> Self {
        Self { reason, ..self }
    }
    const fn suspends(self, suspends: bool) -> Self {
        Self { suspends, ..self }
    }
}

