/// Every TCGEN control row appends its predicate contract.
macro_rules! tcgen_control_reason {
    () => {
        "instruction predicates gate all operand reads and allocation, completion, permit and ordering effects; aligned forms retain full-warp participation requirements"
    };
    ($reason:literal) => {
        concat!($reason, "; ", tcgen_control_reason!())
    };
}
/// Every raw TCGEN MMA row appends its collector and predicate contract.
macro_rules! tcgen_mma_reason {
    ($($part:expr),+) => {
        concat!($($part,)+ "; collectors track per-issuer fill/use/lastuse/discard and independent WS B0..B3 slots; instruction predicates gate register reads and issue with the same lane mask; executed instructions retain PTX-permitted operand reloads and ordinary async memory footprints")
    };
}
macro_rules! ti16_transpose_note {
    () => {
        "TI16 transpose remains unmodeled: PTX 9.4 Table 51 requires zero descriptor transpose bits but Table 62 lists support; native SM107 verification is unavailable"
    };
}
macro_rules! tmem_transpose_note {
    () => {
        "TMEM A must be K-major: an active transpose descriptor is an error, as specified by NVIDIA's tcgen05 programming guide and SM100 UMMA wrappers; shared-A transpose retains the format-specific layout rules"
    };
}
